create function studioflow_private.seed_starter_packages(menu jsonb,candidates jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare result jsonb:=coalesce(menu,'[]'); item jsonb; packages_count integer;
begin
 select count(*) into packages_count from jsonb_array_elements(result) s where concat(s->>'category',' ',s->>'name')~*'package|combo|bundle';
 for item in select value from jsonb_array_elements(coalesce(candidates,'[]')) loop
  exit when packages_count>=5 or jsonb_array_length(result)>=500;
  if not exists(select 1 from jsonb_array_elements(result) s where s->>'id'=item->>'id' or lower(s->>'name')=lower(item->>'name')) then result:=result||jsonb_build_array(item);packages_count:=packages_count+1;end if;
 end loop;
 return result;
end $$;
revoke all on function studioflow_private.seed_starter_packages(jsonb,jsonb) from public,anon,authenticated;
create function studioflow_private.initialize_starter_packages() returns trigger language plpgsql security definer set search_path='' as $$
declare template text:=coalesce(new.draft->'profile'->>'businessType',new.template_id,'hair_salon'); candidates jsonb; menu jsonb;
begin
 if auth.uid() is not null and auth.uid()<>new.user_id then raise exception 'Own workspace required' using errcode='42501';end if;
 if new.draft->'profile'->>'businessType' is null then return new;end if;
 if coalesce(new.draft->'profile'->>'serviceCatalogueInitialized','false')<>'true' and jsonb_array_length(coalesce(new.draft->'services','[]'))=0 then return new;end if;
 if new.draft->'profile'->>'packageCatalogueInitialized'='true' then return new;end if;
 select packages into candidates from studioflow_private.starter_package_catalogues where template_id=template;
 if candidates is null then return new;end if;
 menu:=studioflow_private.seed_starter_packages(coalesce(new.draft->'services','[]'),candidates);
 new.draft:=jsonb_set(jsonb_set(new.draft,'{profile}',coalesce(new.draft->'profile','{}')||jsonb_build_object('packageCatalogueInitialized',true)),'{services}',menu);
 return new;
end $$;
revoke all on function studioflow_private.initialize_starter_packages() from public,anon,authenticated;
create trigger studioflow_initialize_packages before insert or update of draft on public.studioflow_accounts for each row execute function studioflow_private.initialize_starter_packages();
-- Existing owner menus and published snapshots receive real service IDs. Existing
-- offerings are preserved, and the marker prevents deleted packages resurfacing.
update public.studioflow_accounts set draft=draft,revision=revision+1,updated_at=now() where coalesce(draft->'profile'->>'packageCatalogueInitialized','false')<>'true';
update public.studioflow_websites w set content=jsonb_set(jsonb_set(w.content,'{profile}',coalesce(w.content->'profile','{}')||jsonb_build_object('packageCatalogueInitialized',true)),'{services}',studioflow_private.seed_starter_packages(coalesce(w.content->'services','[]'),(select coalesce(jsonb_agg(s),'[]') from jsonb_array_elements(a.draft->'services') s where concat(s->>'category',' ',s->>'name')~*'package|combo|bundle'))) from public.studioflow_accounts a where a.user_id=w.owner_id;
-- Store the matching template package options in the database catalogue too.
update public.studioflow_templates t set config=jsonb_set(t.config,'{services}',studioflow_private.seed_starter_packages(coalesce(t.config->'services','[]'),c.packages)),updated_at=now() from studioflow_private.starter_package_catalogues c where c.template_id=t.id;
